                   {"id": 7, "name": "grace", "org_id": 1}),
            _event("DELETE", "reviews",
                   {"id": "r1", "user_id": 7, "score": 1}, None),
            _event("UPDATE", "users",
                   {"id": 7, "name": "grace", "org_id": 1},
                   {"id": 7, "name": "grace", "org_id": 1}),
            _event("INSERT", "reviews", None,
                   {"id": "r1", "user_id": 7, "score": 11}),
            _event("UPDATE", "users",
                   {"id": 7, "name": "grace", "org_id": 1},
